style.css:
@-moz-document domain("gemini.google.com") {
/* Gemini - Hacker Green Glass v1.0.15 */

/* ChatGPT Hacker Green Glass wallpaper */
html {
  color-scheme: dark !important;
  background-color: #0a0a0a !important;
}
html body {
  background-color: #0a0a0a !important;
  background-image: linear-gradient(to right, rgba(130,255,167,.13) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(130,255,167,.13) 1px, transparent 1px),
    repeating-linear-gradient(to bottom, rgba(10,10,10,0) 0px, rgba(10,10,10,0) 3px, rgba(105,255,153,.035) 3px, rgba(105,255,153,.035) 4px) !important;
  background-size: 40px 40px, 40px 40px, 100% 4px !important;
  background-position: 0 0 !important;
  background-repeat: repeat !important;
  background-attachment: fixed !important;
}
body,
bard-app,
button, input, textarea, select,
[role="button"], [role="menuitem"], [role="option"], [role="tab"],
[contenteditable="true"], .ql-editor, .markdown,
pre, code, kbd, samp {
  font-family: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", Consolas, "Lucida Console", "Courier New", monospace !important;
}
body, bard-app, main, chat-window, chat-window-content, .conversation-container,
.markdown, .model-response-text, .query-text, .ql-editor,
h1, h2, h3, h4, h5, h6, p, li, dt, dd, label,
button, input, textarea, select, [role="button"],
[role="menuitem"], [role="option"], [role="tab"] {
  color: #d9ffe6 !important;
}
a, .markdown a, .markdown a code {
  color: #00ff66 !important;
}
a:hover, .markdown a:hover {
  color: #b6ffc5 !important;
  text-shadow: 0 0 8px rgba(0,255,102,.45) !important;
}
small, .disclaimer, hallucination-disclaimer,
.hallucination-disclaimer, .secondary-text, .mat-mdc-option .mdc-list-item__secondary-text {
  color: #a5ffb7 !important;
}
::selection {
  background-color: #00ff66 !important;
  color: #001b09 !important;
}

/* Transparent app shell and gutters */
bard-app, .app-root, .app-container, main,
mat-sidenav-container, mat-drawer-container, .mat-drawer-container,
mat-sidenav-content, mat-drawer-content, .mat-drawer-content,
.content-container, .main-content, .chat-window, chat-window,
.chat-container, chat-window-content, .chat-history,
.conversation-container, .chat-history-scroll-container,
.bottom-container, input-container, .input-container, .input-area-container,
.input-gradient, .input-gradient::before, .input-gradient::after,
.welcome-container, .home-container {
  background-color: transparent !important;
  background-image: none !important;
}

