  background-image: none !important;
  border-color: rgba(0,255,102,.32) !important;
  box-shadow: inset 0 0 0 1px rgba(0,255,102,.14), 0 0 18px rgba(0,255,102,.12) !important;
}
mat-sidenav, mat-drawer, .mat-drawer {
  box-shadow: inset -1px 0 0 rgba(0,255,102,.38), 5px 0 18px rgba(0,255,102,.14) !important;
}
